(3311702, 461095, 57378, '<td valign="top">I like the idea - For me it''s just a little too contrived. This could have been much better I think if you had just have used the mussel shell in the place it is on it''s own. I think it would have had much more impact. Nice idea though.</td>', 'I like the idea - For me it''s just a little too contrived. This could have been much better I think if you had just have used the mussel shell in the place it is on it''s own. I think it would have had much more impact. Nice idea though.', '2007-02-01 04:45:40.000000', NULL, 1),
(3311703, 459355, 57378, '<td valign="top">Nice and bright!</td>', 'Nice and bright!', '2007-02-01 04:45:51.000000', NULL, 1),
