(3322736, 461220, 49753, '<td valign="top">Well. Maybe next time less flash (the eyes are really ... unnatural) and more blur (The cat doesnt drop off from the background very well).</td>', 'Well. Maybe next time less flash (the eyes are really ... unnatural) and more blur (The cat doesnt drop off from the background very well).', '2007-02-03 12:51:41.000000', NULL, 1),
(3322738, 461697, 49753, '<td valign="top">Great capture. i like the hard shadow on it. But maybe a bit more sharpness on the first bubble would have been great.</td>', 'Great capture. i like the hard shadow on it. But maybe a bit more sharpness on the first bubble would have been great.', '2007-02-03 12:52:23.000000', NULL, 1),
(3322741, 459882, 49753, '<td valign="top">Lovely contrasts between the color of the bloom and the background but i wish there would be a bit more sharpness on the focus details.</td>', 'Lovely contrasts between the color of the bloom and the background but i wish there would be a bit more sharpness on the focus details.', '2007-02-03 12:53:22.000000', NULL, 1),
(3322843, 460890, 73246, '<td valign="top">Who Me..yes you what a great shot. Simple but it tells alot</td>', 'Who Me..yes you what a great shot. Simple but it tells alot', '2007-02-03 13:32:51.000000', NULL, 1),
(3322866, 461044, 49753, '<td valign="top">It appears a bit palish. Maybe some more contrasts would be great.</td>', 'It appears a bit palish. Maybe some more contrasts would be great.', '2007-02-03 13:43:25.000000', NULL, 1),
(3322870, 461202, 49753, '<td valign="top">I guess you used a flash. That is not that good, because there are some really unestethic reflections on the elefant. The shallow is well done.</td>', 'I guess you used a flash. That is not that good, because there are some really unestethic reflections on the elefant. The shallow is well done.', '2007-02-03 13:44:24.000000', NULL, 1),
