(3323432, 461576, 67774, '<td valign="top">NICE BOKEH</td>', 'NICE BOKEH', '2007-02-03 16:12:40.000000', NULL, 1),
(3323445, 461301, 72714, '<td valign="top">I like the triangles created by the black and white keys but I think the finger should have come in from the left in a more ''natural'' keyboard pose.</td>', 'I like the triangles created by the black and white keys but I think the finger should have come in from the left in a more ''natural'' keyboard pose.', '2007-02-03 16:14:52.000000', NULL, 1),
(3323454, 461377, 72714, '<td valign="top">The shallow DOF is good but the photograph would be better if the white twigs in front of the lizzards face were removed.</td>', 'The shallow DOF is good but the photograph would be better if the white twigs in front of the lizzards face were removed.', '2007-02-03 16:16:30.000000', NULL, 1),
(3323458, 461201, 72714, '<td valign="top">Gorgeous colours and I like the corner composition. I just find the big dark ''blob'' a bit distracting.</td>', 'Gorgeous colours and I like the corner composition. I just find the big dark ''blob'' a bit distracting.', '2007-02-03 16:17:31.000000', NULL, 1),
(3323478, 458348, 72714, '<td valign="top">The dimensions in this photo are really good. It could have been just a hand with a neckchain but including the figure in the background was well thought out. Excellent!</td>', 'The dimensions in this photo are really good. It could have been just a hand with a neckchain but including the figure in the background was well thought out. Excellent!', '2007-02-03 16:21:38.000000', NULL, 1),
(3323495, 459935, 72714, '<td valign="top">Beautiful vibrant colours and a nice contrast to the snow. Almost like fire and ice!</td>', 'Beautiful vibrant colours and a nice contrast to the snow. Almost like fire and ice!', '2007-02-03 16:25:23.000000', NULL, 1),
(3323501, 461324, 72714, '<td valign="top">Excellent! I love this photograph and if I had to change anything it would be to remove the small spot under the focus line. Just the one.</td>', 'Excellent! I love this photograph and if I had to change anything it would be to remove the small spot under the focus line. Just the one.', '2007-02-03 16:27:09.000000', NULL, 1),
(3323508, 458455, 72714, '<td valign="top">I think focusing on the points of the darts would have had more impact as this is where the two different objects (the darts and the board) ''meet''.</td>', 'I think focusing on the points of the darts would have had more impact as this is where the two different objects (the darts and the board) ''meet''.', '2007-02-03 16:29:18.000000', NULL, 1),
(3323521, 460436, 72714, '<td valign="top">Fantastic colours and I love the bubbles! I think the tight crop on the front glas really works well.</td>', 'Fantastic colours and I love the bubbles! I think the tight crop on the front glas really works well.', '2007-02-03 16:33:00.000000', NULL, 1),
(3323534, 461368, 72714, '<td valign="top">The background colour compliments the birds colouring really well.</td>', 'The background colour compliments the birds colouring really well.', '2007-02-03 16:36:57.000000', NULL, 1),
(3323550, 461499, 72714, '<td valign="top">Excellent photo! The shell ties in perfectly with the lighthouse.</td>', 'Excellent photo! The shell ties in perfectly with the lighthouse.', '2007-02-03 16:40:47.000000', NULL, 1),
(3323562, 461686, 72714, '<td valign="top">I would remove the distracting brown (wooden?) object from the bottom right hand corner. The photo would then look like rather nice duotone.</td>', 'I would remove the distracting brown (wooden?) object from the bottom right hand corner. The photo would then look like rather nice duotone.', '2007-02-03 16:43:48.000000', NULL, 1),
(3323568, 461576, 72714, '<td valign="top">Gorgeous texture on the feathers but a bit blown out on the back of the head.</td>', 'Gorgeous texture on the feathers but a bit blown out on the back of the head.', '2007-02-03 16:45:03.000000', NULL, 1),
(3323577, 459419, 72714, '<td valign="top">This is so cute! Just a little bundle of fluffy feathers! Well photographed, good focus and nice, uncluttered background. Well done!</td>', 'This is so cute! Just a little bundle of fluffy feathers! Well photographed, good focus and nice, uncluttered background. Well done!', '2007-02-03 16:46:25.000000', NULL, 1),
(3323584, 460884, 72714, '<td valign="top">Fantastic colours and I like the composition. Is the DOF shallow enough though?</td>', 'Fantastic colours and I like the composition. Is the DOF shallow enough though?', '2007-02-03 16:47:29.000000', NULL, 1),
(3323598, 461623, 72714, '<td valign="top">Moisture droplets always make me thirsty! lol. I like the colours and focus point but maybe using rule of thirds would have a better impact?</td>', 'Moisture droplets always make me thirsty! lol. I like the colours and focus point but maybe using rule of thirds would have a better impact?', '2007-02-03 16:49:16.000000', NULL, 1),
(3323621, 461298, 72714, '<td valign="top">Wow!!! As this picture was loading and I saw the feet pointing skyward, I knew this was going to be spectacular! Fantastic DOP, sharply focused, excellent colour tones. Well done! Out of curiosity, was this picture rotated or is this a real dive?</td>', 'Wow!!! As this picture was loading and I saw the feet pointing skyward, I knew this was going to be spectacular! Fantastic DOP, sharply focused, excellent colour tones. Well done! Out of curiosity, was this picture rotated or is this a real dive?', '2007-02-03 16:52:33.000000', NULL, 1),
(3323626, 460572, 72714, '<td valign="top">Beautiful! The green background is very complimentary!</td>', 'Beautiful! The green background is very complimentary!', '2007-02-03 16:53:42.000000', NULL, 1),
(3323638, 460049, 72714, '<td valign="top">Such sad eyes! I have the greatest respect for people who have been through something like this in their lifetimes. I love the way the figure behind is a mirroring the actions of the old man. Well photographed.</td>', 'Such sad eyes! I have the greatest respect for people who have been through something like this in their lifetimes. I love the way the figure behind is a mirroring the actions of the old man. Well photographed.', '2007-02-03 16:57:01.000000', NULL, 1),
(3323640, 461102, 72714, '<td valign="top">Well composed and very striking!</td>', 'Well composed and very striking!', '2007-02-03 16:57:36.000000', NULL, 1),
(3323645, 461290, 72714, '<td valign="top">What a gorgeous photo of Ben! I like the tight crop and the fact that we can see his body in the background. Good lighting.</td>', 'What a gorgeous photo of Ben! I like the tight crop and the fact that we can see his body in the background. Good lighting.', '2007-02-03 16:59:29.000000', NULL, 1),
(3323647, 461413, 72714, '<td valign="top">Well composed, beautiful colours and I like the fact that you included the grass mounds in the foreground to add to the dimension.</td>', 'Well composed, beautiful colours and I like the fact that you included the grass mounds in the foreground to add to the dimension.', '2007-02-03 17:00:49.000000', NULL, 1),
(3323650, 460397, 72714, '<td valign="top">My eyes couldn''t find any point of interest to settle on. Too much of the same thing in focus, I think.</td>', 'My eyes couldn''t find any point of interest to settle on. Too much of the same thing in focus, I think.', '2007-02-03 17:02:14.000000', NULL, 1),
(3323651, 459337, 72714, '<td valign="top">I like the way the flowers curve around the shape of the cross in the background and the contrast between the pink and the white makes a really striking image.</td>', 'I like the way the flowers curve around the shape of the cross in the background and the contrast between the pink and the white makes a really striking image.', '2007-02-03 17:03:32.000000', NULL, 1),
