(3323663, 461607, 72714, '<td valign="top">OMG! Good thing I''m not afraid of snakes! This is a brilliant picture, especially having activated the shutter as the tongue came out. The head is also nicely placed in an uncluttered area to make it stand out nicely from the background.</td>', 'OMG! Good thing I''m not afraid of snakes! This is a brilliant picture, especially having activated the shutter as the tongue came out. The head is also nicely placed in an uncluttered area to make it stand out nicely from the background.', '2007-02-03 17:08:57.000000', NULL, 1),
(3323670, 461551, 72714, '<td valign="top">A striking image! I like the placement of the reflections halfway through the frame.</td>', 'A striking image! I like the placement of the reflections halfway through the frame.', '2007-02-03 17:11:24.000000', NULL, 1),
(3323679, 461581, 72714, '<td valign="top">Nice photo but it would have been better if the bug was facing the camera and the focus was on it''s head.</td>', 'Nice photo but it would have been better if the bug was facing the camera and the focus was on it''s head.', '2007-02-03 17:13:21.000000', NULL, 1),
