(3333392, 461551, 54540, '<td valign="top">Mark my words, I''m looking at a ribbon winner here.  Well done!</td>', 'Mark my words, I''m looking at a ribbon winner here.  Well done!', '2007-02-06 00:57:31.000000', NULL, 1),
(3333416, 460376, 54540, '<td valign="top">Excellent composition and use of DOF!  For my tastes, I''d like to see the roses sharpened just a tad more.  Well done, regardless!</td>', 'Excellent composition and use of DOF!  For my tastes, I''d like to see the roses sharpened just a tad more.  Well done, regardless!', '2007-02-06 01:08:40.000000', NULL, 1),
(3333420, 458417, 54540, '<td valign="top">Wow!  Clever idea for such a simple setup!  Well done!</td>', 'Wow!  Clever idea for such a simple setup!  Well done!', '2007-02-06 01:10:33.000000', NULL, 1),
(3333429, 461093, 54540, '<td valign="top">Awesome!  (former climber here)  I hope the voters get it, but regardless - you have my vote!  Well done!  The DOF gets the viewer focused on the subject here!</td>', 'Awesome!  (former climber here)  I hope the voters get it, but regardless - you have my vote!  Well done!  The DOF gets the viewer focused on the subject here!', '2007-02-06 01:14:09.000000', NULL, 1),
(3333485, 461298, 54540, '<td valign="top">FANTASTIC capture!  I really like this shot.  Kudos!  Not my favorite for shallow DOF, but an excellent case of right spot at the right time!  Well done and best of luck in the challenge!  Wow!</td>', 'FANTASTIC capture!  I really like this shot.  Kudos!  Not my favorite for shallow DOF, but an excellent case of right spot at the right time!  Well done and best of luck in the challenge!  Wow!', '2007-02-06 01:50:46.000000', NULL, 1),
(3333524, 460899, 73608, '<td valign="top">I like the sharpness against the blurred background and the similar colors in foreground/background with the contrasting blue in the middle.</td>', 'I like the sharpness against the blurred background and the similar colors in foreground/background with the contrasting blue in the middle.', '2007-02-06 02:29:42.000000', NULL, 1),
(3333526, 459473, 73608, '<td valign="top">Nice framing and contrast. I think the foreground could be a bit more blurred.</td>', 'Nice framing and contrast. I think the foreground could be a bit more blurred.', '2007-02-06 02:30:38.000000', NULL, 1),
(3333532, 459903, 73608, '<td valign="top">I like highlighting the one rock via both color and focus. I think it''d be stronger without the two out of focus colored items.</td>', 'I like highlighting the one rock via both color and focus. I think it''d be stronger without the two out of focus colored items.', '2007-02-06 02:32:13.000000', NULL, 1),
(3333535, 461579, 73608, '<td valign="top">The subject matter is a favorite of mine (SoS). Good photographic interpretation too.</td>', 'The subject matter is a favorite of mine (SoS). Good photographic interpretation too.', '2007-02-06 02:33:54.000000', NULL, 1),
(3333537, 460008, 73608, '<td valign="top">I like the combination focus and different orientation to highlight the one coin. Nice leading lines with the arrangement too.</td>', 'I like the combination focus and different orientation to highlight the one coin. Nice leading lines with the arrangement too.', '2007-02-06 02:35:04.000000', NULL, 1);
