(3687936, 459337, 50695, '<td valign="top">my favorite thing about this image is that you''ve cropped off the edges of the tombstone so it completely takes over the background. It becomes an embossed sky of stone. I might try enhancing this effect by not centering the cross, but that might screw up the composition.</td>', 'my favorite thing about this image is that you''ve cropped off the edges of the tombstone so it completely takes over the background. It becomes an embossed sky of stone. I might try enhancing this effect by not centering the cross, but that might screw up the composition.', '2007-05-23 18:58:30.000000', NULL, 0),
(3688517, 459337, 51597, '<td valign="top">The Title "life in Death" really fits this picture.. <br/>The flowers are very elegant and beautiful.. <br/> <br/>Thank you for wishing me well.. <br/> <br/>You are a Great Photographer! <br/></td>', 'The Title "life in Death" really fits this picture.. The flowers are very elegant and beautiful..  Thank you for wishing me well..  You are a Great Photographer! ', '2007-05-23 21:37:47.000000', NULL, 0),
(3690382, 459337, 67697, '<td valign="top">Love how you took it from the perspective of the flowers arcing over the cross.  Love the vibrant pink contrast vs. the white cold stone.</td>', 'Love how you took it from the perspective of the flowers arcing over the cross.  Love the vibrant pink contrast vs. the white cold stone.', '2007-05-24 11:06:12.000000', NULL, 0),
(3767964, 461038, 79602, '<td valign="top">Love the DOF in this one.  I have a Canon 100mm Macro, and I love using it.  It''s amazing what you can do with these lenses!  Great shot!!</td>', 'Love the DOF in this one.  I have a Canon 100mm Macro, and I love using it.  It''s amazing what you can do with these lenses!  Great shot!!', '2007-06-11 13:09:06.000000', NULL, 0),
(3795450, 460121, 51597, '<td valign="top">Wow!! In awe here.. Great Detail..</td>', 'Wow!! In awe here.. Great Detail..', '2007-06-17 23:36:55.000000', NULL, 0),
(3823899, 459309, 47294, '<td valign="top">Very nice work Hoffy!  Great and effective use of stronge DOF.</td>', 'Very nice work Hoffy!  Great and effective use of stronge DOF.', '2007-06-23 10:36:29.000000', NULL, 0),
(3847413, 461038, 66635, '<td valign="top">Man!  That''s really nice.  It''s so vivid and sharp that I can feel the sharp points of the needles and the texture of the cactus'' skin.</td>', 'Man!  That''s really nice.  It''s so vivid and sharp that I can feel the sharp points of the needles and the texture of the cactus'' skin.', '2007-06-29 01:41:50.000000', NULL, 0),
